import * as fs from 'fs';
import * as readline from 'readline';

const rl = readline.createInterface({
  input: fs.createReadStream('C:/Users/ziani/.gemini/antigravity-ide/brain/b2c99fea-3c4e-42de-af09-ab5855a7fa4e/.system_generated/logs/transcript.jsonl'),
  crlfDelay: Infinity
});

rl.on('line', (line) => {
  if (line.includes('export const KOSOVO_METOHIJA_FEATURE')) {
    const obj = JSON.parse(line);
    console.log('Found line in step:', obj.step_index);
    if (obj.tool_calls) {
      console.log('Tool calls in step:', JSON.stringify(obj.tool_calls).slice(0, 500));
